Read the Main sheet, group rows by staff number, and map each allowance description to one of five transposed columns. Write the A:G headers, allowance headers, and a Total header into row 1 of Output Required. Fill one row per staff member with the base fields, transposed allowance amounts, and the row total in column M.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

main = vals["Main"]
out_name = "Output Required"
if out_name not in wb.sheetnames:
    out = wb.create_sheet(out_name)
else:
    out = wb[out_name]

def clean(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def allowance_index(desc):
    if desc is None:
        return None
    d = str(desc).strip().lower()
    if d == "basic":
        return 0
    if d in {"housing allowance", "housing allowances"}:
        return 1
    if d in {"transport allowance", "transport allowances"}:
        return 2
    if d in {"other allowance", "other allowances"}:
        return 3
    if d in {"social allowance", "social allowances"}:
        return 4
    if d.startswith("basic"):
        return 0
    if d.startswith("housing"):
        return 1
    if d.startswith("transport"):
        return 2
    if d.startswith("other"):
        return 3
    if d.startswith("social"):
        return 4
    return None

headers = [clean(main.cell(row=1, column=c).value) for c in range(1, 8)]
allowance_headers = [
    "Basic",
    "Housing Allowance",
    "Transport Allowance",
    "Other Allowance",
    "Social Allowance"
]

groups = []
group_map = {}

for r in range(2, main.max_row + 1):
    staff = clean(main.cell(row=r, column=1).value)
    if staff is None:
        continue

    key = staff
    if isinstance(key, str):
        key = key.strip()

    if key not in group_map:
        base = [clean(main.cell(row=r, column=c).value) for c in range(1, 8)]
        group_map[key] = {"base": base, "amounts": [None] * 5}
        groups.append(group_map[key])

    g = group_map[key]
    idx = allowance_index(main.cell(row=r, column=8).value)
    if idx is not None:
        amt = clean(main.cell(row=r, column=9).value)
        if isinstance(amt, str):
            try:
                f = float(amt)
                amt = int(f) if f.is_integer() else f
            except ValueError:
                amt = None
        g["amounts"][idx] = amt

# Clear the graded answer region before writing values.
for r in range(1, 4):
    for c in range(1, 14):
        out.cell(row=r, column=c).value = None

# Row 1: copied main headers A:G, transposed allowance headers H:L, total header M.
for c, v in enumerate(headers, start=1):
    if v is not None:
        out.cell(row=1, column=c).value = v

for c, v in enumerate(allowance_headers, start=8):
    out.cell(row=1, column=c).value = v

out.cell(row=1, column=13).value = "Total"

# Rows 2-3: one row per staff member.
for i, g in enumerate(groups[:2]):
    r = i + 2

    for c, v in enumerate(g["base"], start=1):
        if v is not None:
            out.cell(row=r, column=c).value = v

    for c, amt in enumerate(g["amounts"], start=8):
        if amt is not None:
            out.cell(row=r, column=c).value = amt

    total = 0
    for amt in g["amounts"]:
        if isinstance(amt, (int, float)):
            total += amt

    out.cell(row=r, column=13).value = total

wb.save(OUT)

print("groups:", len(groups))
for g in groups[:2]:
    print(g["base"][0], g["amounts"], sum(x for x in g["amounts"] if isinstance(x, (int, float))))
